import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { validateExperimental } from "../../app/api/_lib/experimental.js";
import { timestamp, inputDigest } from "../../app/api/_lib/contracts.js";
import { selectExperimental } from "../../app/lib/experimental-selection.js";
// Synthetic race fixture generated by the Python lifecycle test builder.
const fixture = JSON.parse(
  fs.readFileSync(
    new URL("../fixtures/experimental-forecast.json", import.meta.url),
  ),
);
test("Python fitted forecast recomputes identically in the API validator", () => {
  assert.equal(validateExperimental(fixture, timestamp, inputDigest), fixture);
});
test("changed model scores, target history, inputs and chronology are rejected", () => {
  for (const change of [
    (p) => p.full_grid[0].ranking_score++,
    (p) => (p.inputs.history[0].event = p.event),
    (p) => (p.inputs.entrants[0].name = "Changed"),
    (p) => (p.inputs.model_hash = "wrong"),
    (p) => (p.generated_at = p.event.start_at),
  ]) {
    const p = structuredClone(fixture);
    change(p);
    assert.throws(() => validateExperimental(p, timestamp, inputDigest));
  }
});
test("selection keeps matching saved model forecasts and rejects a different event", () => {
  const now = Date.parse("2030-03-09T12:00:00Z"),
    current = { state: "UPCOMING", event: fixture.event };
  assert.equal(selectExperimental([fixture], current, now), fixture);
  assert.equal(
    selectExperimental(
      [fixture],
      { ...current, state: "UPDATING" },
      Date.parse(fixture.event.start_at),
    ),
    fixture,
  );
  assert.equal(
    selectExperimental(
      [fixture],
      { ...current, event: { ...fixture.event, id: "other" } },
      now,
    ),
    null,
  );
  assert.equal(
    selectExperimental(
      [fixture],
      {
        ...current,
        event: { ...fixture.event, start_at: "2030-03-11T14:00:00Z" },
      },
      now,
    ),
    null,
  );
});
